// Official truthsrc.product-generator/v2 entrypoint: scala-cqrs-play-service:2
// Strict superset of scala-cqrs-play-service@1 across all 60 Artifact Type families:
//   - Block A: Domain core via 1.0 emitter/families (#1 value-object, #2 domain-entity, #3 event-handler, #45 aggregate-invariant-rules with real eventPostconditions) + EARS NNF simplification + Z3 Axioms + Application Ports + typed CallerContractSpec + *Impl.scala @cloze isolation zones
//   - Block B: Unified `// @generated by truthsrc scala-cqrs-play-service:2` header + semantic stable `@knowledge` anchors + manifest provenance
//   - Block C: 1.0 Aggregate/Protocol/Repository/Bootstrap + Protobuf/Converter/SerializationAdapter (7 curated families) + ExternalAuthority propagation
//   - Block D: Full ReadSide/Projection Suite (#15,#23,#24,#26,#27,#28,#38b), auth-core Play Controllers + AggregateStateApiController + CommandDsl + conf/routes (#34-#37), Orchestration/Saga/Effect/ToolGate/ExternalEventBridge (#13,#25,#40-#44,#46,#38c,#38d), Play service-runtime (#38), project-scaffold (#39), 5-layer Authz PEP/PDP
//   - Multi-Subdomain -> Bounded Context Packaging: `generateScalaCqrsPlayServiceV2ForBc`
import { createHash } from 'node:crypto';
import { existsSync, mkdirSync, readdirSync, readFileSync, rmdirSync, rmSync, unlinkSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { registerCodegenPlugin } from '../../lib/v2/codegen/interface.mjs';
import { resolveRuntimeProfile } from '../../lib/runtime-profile.mjs';
import { writeV2KnowledgeGraph } from '../../lib/v2/knowledge-db.mjs';
import { scalaStrictCodegenPlugin, syncMissingScalaMethods } from '../../lib/v2/bridge/v1-strict-scala.mjs';
import { emitV1BlockC, emitV1BlockD } from '../../lib/v2/bridge/v1-strict-block-cd.mjs';
import { emitV1OrchestrationSuite } from '../../lib/v2/bridge/v1-strict-orchestration.mjs';

const __dirname = dirname(fileURLToPath(import.meta.url));
export const GENERATOR_MANIFEST = Object.freeze(
  JSON.parse(readFileSync(join(__dirname, 'generator.json'), 'utf8')),
);
export const GENERATED_HEADER_SCALA = `// @generated by truthsrc ${GENERATOR_MANIFEST.name}:${GENERATOR_MANIFEST.version}`;
export const GENERATED_HEADER_CONF = `# @generated by truthsrc ${GENERATOR_MANIFEST.name}:${GENERATOR_MANIFEST.version}`;

function stampGeneratedHeader(relPath, content, canonicalSha256) {
  const shaLineScala = `// @canonical-v2 ${canonicalSha256}`;
  const shaLineConf = `# @canonical-v2 ${canonicalSha256}`;
  if (relPath.endsWith('.scala') || relPath.endsWith('.proto') || relPath.endsWith('.sbt')) {
    const cleaned = content.replace(/^\/\/\s*@generated[^\n]*\n(?:\/\/\s*@canonical[^\n]*\n)?/u, '');
    return `${GENERATED_HEADER_SCALA}\n${shaLineScala}\n${cleaned}`;
  }
  if (relPath.endsWith('.conf') || relPath.endsWith('/routes') || relPath === 'routes' || relPath.endsWith('.properties')) {
    const cleaned = content.replace(/^#\s*@generated[^\n]*\n(?:#\s*@canonical[^\n]*\n)?/u, '');
    return `${GENERATED_HEADER_CONF}\n${shaLineConf}\n${cleaned}`;
  }
  return content;
}

function mapV1PathToV2Scaffold(rawPath) {
  if (rawPath.startsWith('app/protobuf/')) {
    return `generated-scaffold/protobuf/${rawPath.slice('app/protobuf/'.length)}`;
  }
  if (rawPath.startsWith('app/')) {
    return `generated-scaffold/scala/${rawPath.slice('app/'.length)}`;
  }
  return `generated-scaffold/${rawPath}`;
}

function writeArtifact(outDir, relPath, content, { overwrite = true } = {}) {
  const dest = join(outDir, relPath);
  if (!overwrite && existsSync(dest)) {
    return { path: relPath, absPath: dest, skippedExisting: true, sha256: null };
  }
  mkdirSync(dirname(dest), { recursive: true });
  writeFileSync(dest, content, 'utf8');
  return {
    path: relPath,
    absPath: dest,
    skippedExisting: false,
    sha256: createHash('sha256').update(content).digest('hex'),
  };
}

function dedupBy(items, keyFn) {
  const seen = new Set();
  const out = [];
  for (const item of items) {
    const k = keyFn(item);
    if (seen.has(k)) continue;
    seen.add(k);
    out.push(item);
  }
  return out;
}

function stableStructureSignature(item) {
  const stripMeta = v => {
    if (Array.isArray(v)) return v.map(stripMeta);
    if (v && typeof v === 'object') {
      const out = {};
      for (const k of Object.keys(v).sort()) {
        if (k === 'sourceFile' || k === 'description' || k === 'doc' || k === 'notes') continue;
        out[k] = stripMeta(v[k]);
      }
      return out;
    }
    return v;
  };
  return JSON.stringify(stripMeta(item));
}

function dedupStructuralChecked(canonicals, getter, kind, keyFn) {
  const seen = new Map();
  const out = [];
  for (const c of canonicals) {
    const sub = c.subdomain || c.context || 'unknown';
    for (const item of getter(c) ?? []) {
      const key = keyFn(item);
      const sig = stableStructureSignature(item);
      if (seen.has(key)) {
        const prev = seen.get(key);
        if (prev.sig !== sig) {
          throw new Error(
            `BC_MERGE_CONFLICT: conflicting ${kind} "${key}" across subdomains (${prev.sub} vs ${sub}); unify the shared definition or rename one of them before monolith/BC packaging`,
          );
        }
        continue;
      }
      seen.set(key, { sig, sub });
      out.push(item);
    }
  }
  return out;
}

/**
 * Merge multiple subdomain canonical-v2.json documents assigned to a single Bounded Context
 * into one unified canonical model, deriving cross-BC external integrations from domainMap.
 */
export function mergeCanonicalsForBc(canonicals, { bcName, domainMap = null } = {}) {
  if (!Array.isArray(canonicals) || canonicals.length === 0) {
    throw new Error('BC_MERGE_EMPTY: mergeCanonicalsForBc requires at least one canonical-v2 document');
  }
  const first = canonicals[0];
  const system = domainMap?.system || first.system || 'app';
  const context = bcName || first.context || first.subdomain || 'core';
  const memberSubdomains = new Set(
    canonicals.map(c => c.subdomain || c.context).filter(Boolean),
  );

  // Derive cross-BC inbound external integrations for #46 external-event-bridge
  const externalIntegrations = [];
  const rawIntegrations = domainMap?.integrations ?? domainMap?.contextMap ?? [];
  for (const rel of rawIntegrations) {
    const downstream = rel.downstreamSubdomain || rel.downstream || rel.to || rel.consumer;
    const upstream = rel.upstreamSubdomain || rel.upstream || rel.from || rel.producer;
    if (!downstream || !upstream) continue;
    const targetsThisBc = downstream === context || memberSubdomains.has(downstream);
    const fromOutsideThisBc = upstream !== context && !memberSubdomains.has(upstream);
    if (targetsThisBc && fromOutsideThisBc) {
      const defaultTargetAgg = rel.downstreamTarget ? String(rel.downstreamTarget).split('.')[0] : rel.targetAggregate;
      const rawEvents = rel.events ?? (rel.upstreamEvent ? [rel.upstreamEvent] : (rel.event ? [rel.event] : []));
      for (const ev of rawEvents) {
        const rawEvName = typeof ev === 'string' ? ev : ev.name;
        const evName = String(rawEvName).includes('.') ? String(rawEvName).split('.').pop() : String(rawEvName);
        const targetAgg = typeof ev === 'object' ? (ev.targetAggregate || defaultTargetAgg) : defaultTargetAgg;
        externalIntegrations.push({
          id: (rel.id || `${upstream}-${evName}`).toLowerCase().replace(/[^a-z0-9_-]+/gu, '-'),
          fromContext: upstream,
          event: evName,
          targetAggregate: targetAgg,
          pattern: rel.pattern || 'ACL',
        });
      }
    }
  }

  const behaviors = dedupBy(canonicals.flatMap(c => c.behaviors ?? []), b => `${b.kind}:${b.target}`);
  const clozeSlots = dedupBy(canonicals.flatMap(c => c.clozeSlots ?? []), s => s.slotId || s.target);
  const deterministicCount = behaviors.filter(b => b.theory?.codegenChannel === 'deterministic').length;
  const clozeCount = behaviors.length - deterministicCount;
  const firstSolver = canonicals.find(c => c.verificationSummary?.solver)?.verificationSummary?.solver || 'z3';

  const merged = {
    schemaVersion: first.schemaVersion || 'co-arising.canonical/v2',
    system,
    context,
    boundedContext: context,
    packagedSubdomains: [...memberSubdomains],
    canonicalSha256: createHash('sha256')
      .update(canonicals.map(c => c.canonicalSha256 || '').join(':'))
      .digest('hex'),
    structures: {
      roles: dedupBy(canonicals.flatMap(c => c.structures?.roles ?? []), x => (typeof x === 'string' ? x : x.name)),
      exactTypes: dedupStructuralChecked(canonicals, c => c.structures?.exactTypes, 'exactType', x => x.name),
      valueObjects: dedupStructuralChecked(canonicals, c => c.structures?.valueObjects, 'valueObject', x => x.name),
      readModels: dedupStructuralChecked(canonicals, c => c.structures?.readModels, 'readModel', x => x.name),
      ports: dedupStructuralChecked(canonicals, c => c.structures?.ports, 'port', x => x.name),
      externContracts: dedupStructuralChecked(canonicals, c => c.structures?.externContracts, 'externContract', x => `${x.ownerPort || ''}:${x.name}`),
      aggregates: dedupStructuralChecked(canonicals, c => c.structures?.aggregates, 'aggregate', x => x.name),
      stories: dedupStructuralChecked(canonicals, c => c.structures?.stories, 'story', x => x.name),
      useCases: dedupBy(canonicals.flatMap(c => c.structures?.useCases ?? []), x => x.id || x.name),
      journeys: dedupBy(canonicals.flatMap(c => c.structures?.journeys ?? []), x => x.id || x.name),
      compliance: dedupBy(canonicals.flatMap(c => c.structures?.compliance ?? []), x => x.id || x.name),
      pipelines: dedupBy(canonicals.flatMap(c => c.structures?.pipelines ?? c.pipelines ?? []), x => x.id || x.name),
      sagas: dedupBy(canonicals.flatMap(c => c.structures?.sagas ?? c.sagas ?? []), x => x.name),
      effects: dedupBy(canonicals.flatMap(c => c.structures?.effects ?? c.effects ?? []), x => x.name),
    },
    behaviors,
    eventFolds: dedupBy(canonicals.flatMap(c => c.eventFolds ?? []), f => `${f.aggregate}:${f.event}`),
    clozeSlots,
    verificationSummary: {
      solver: firstSolver,
      passed: true,
      behaviorCount: behaviors.length,
      deterministicCount,
      clozeCount,
    },
  };

  return { mergedCanonical: merged, externalIntegrations };
}

function pruneEmptyAncestors(startDir, stopDir) {
  let cur = resolve(startDir);
  const boundary = resolve(stopDir);
  while (cur.startsWith(boundary) && cur !== boundary) {
    try {
      if (readdirSync(cur).length > 0) break;
      rmdirSync(cur);
      cur = dirname(cur);
    } catch {
      break;
    }
  }
}

export function generateScalaCqrsPlayServiceV2(canonicalV2, {
  outDir,
  packageName = 'example.v2',
  overwriteCloze = false,
  runtimeProfile = null,
  includeCommonKernel = true,
  includeFrameworkLayers = true,
  externalIntegrations = [],
} = {}) {
  const root = resolve(outDir);
  const sha = canonicalV2.canonicalSha256 || 'unsigned';

  const emitCommonKernel = !includeFrameworkLayers && includeCommonKernel;
  const rp = resolveRuntimeProfile({ runtimeProfile });
  const commonPkgDir = rp.commonPackage.split('.').join('/');

  // 1. Block A: 4 core 1.0 domain families (#1,#2,#3,#45 with real eventPostconditions) + Axioms + Application Ports + typed CallerContractSpec + *Impl.scala isolation zones
  //    When emitting full Play/sbt layers, common-core JAR provides CborSerializable & CommonTypes, so omit duplicate CommonKernel sources.
  const blockARes = scalaStrictCodegenPlugin.generate(canonicalV2, {
    outDir: root,
    packageName,
    overwriteCloze,
    runtimeProfile,
    includeCommonKernel: emitCommonKernel,
  });

  // Stamp `// @generated by truthsrc scala-cqrs-play-service:2` on all generated-scaffold files from Block A
  const written = [];
  const writtenMap = new Map();
  for (const rec of blockARes.files) {
    if (rec.path.startsWith('generated-scaffold/') && existsSync(rec.absPath)) {
      const raw = readFileSync(rec.absPath, 'utf8');
      const stamped = stampGeneratedHeader(rec.path, raw, sha);
      const updated = writeArtifact(root, rec.path, stamped, { overwrite: true });
      writtenMap.set(rec.path, updated);
    } else {
      writtenMap.set(rec.path, rec);
    }
  }

  const allFamilies = new Set(blockARes.familiesUsed ?? []);
  const syncedHandwrittenMethods = [...(blockARes.syncedHandwrittenMethods ?? [])];
  const handwrittenDrift = [];

  // 2. Block C & D: Pre-derive Orchestration (for ExternalAuthority propagation into Block C),
  //    then emit Block C + full Block D (ReadSide, auth-core PlayController, AggregateStateApiController, CommandDsl, conf/routes, Saga/Effect, service-runtime, project-scaffold)
  if (includeFrameworkLayers) {
    const orchestration = emitV1OrchestrationSuite(canonicalV2, {
      packageName,
      runtimeProfile,
      externalIntegrations,
    });

    const blockC = emitV1BlockC(canonicalV2, {
      packageName,
      runtimeProfile,
      authorityAggs: orchestration.authorityAggs,
      externalProducersByAgg: orchestration.externalProducersByAgg,
    });
    for (const f of blockC.familiesUsed) allFamilies.add(f);
    for (const [rawPath, content] of Object.entries(blockC.files)) {
      const relPath = mapV1PathToV2Scaffold(rawPath);
      // Preserve Block A's richer Computations trait (with Noop) if already emitted
      if (relPath.endsWith('Computations.scala') && writtenMap.has(relPath)) continue;
      const stamped = stampGeneratedHeader(relPath, content, sha);
      writtenMap.set(relPath, writeArtifact(root, relPath, stamped, { overwrite: true }));
    }

    const pkgDir = packageName.split('.').join('/');
    const hwBindingsRel = `handwritten/scala/${pkgDir}/modules/HandwrittenBindingsModule.scala`;
    const hwBindingsAbs = join(root, hwBindingsRel);
    const existingHwBindings = existsSync(hwBindingsAbs) ? readFileSync(hwBindingsAbs, 'utf8') : null;
    const hwAlreadyInstallsProjection = Boolean(
      existingHwBindings && /install\s*\(\s*new\s+[A-Za-z0-9_]+ProjectionModule\s*\(\s*\)\s*\)/u.test(existingHwBindings),
    );
    if (existingHwBindings && !/\bGeneratedBindingsModule\b/u.test(existingHwBindings)) {
      handwrittenDrift.push({
        path: hwBindingsRel,
        code: 'HANDWRITTEN_BINDINGS_MISSING_GENERATED_MODULE',
        message: 'existing HandwrittenBindingsModule does not install GeneratedBindingsModule; newly added bindings may not be wired at runtime',
      });
    }

    const blockD = emitV1BlockD(canonicalV2, {
      packageName,
      runtimeProfile,
      protoPaths: blockC.protoPaths,
      orchestration,
      externalIntegrations,
      nonEmptyComputationsAggs: new Set(blockARes.nonEmptyComputationsAggs ?? []),
      installProjectionInGeneratedBindings: !hwAlreadyInstallsProjection,
    });
    for (const f of blockD.familiesUsed) allFamilies.add(f);
    for (const [rawPath, content] of Object.entries(blockD.files)) {
      const relPath = mapV1PathToV2Scaffold(rawPath);
      const stamped = stampGeneratedHeader(relPath, content, sha);
      writtenMap.set(relPath, writeArtifact(root, relPath, stamped, { overwrite: true }));
    }
    for (const [hwPath, content] of Object.entries(blockD.handwrittenFiles ?? {})) {
      const hwRec = writeArtifact(root, hwPath, content, { overwrite: overwriteCloze });
      if (hwRec.skippedExisting && blockD.handwrittenMethodSpecs?.[hwPath]) {
        const syncRes = syncMissingScalaMethods(hwRec.absPath, blockD.handwrittenMethodSpecs[hwPath]);
        if (syncRes.synced) {
          syncedHandwrittenMethods.push({ path: hwPath, addedMethods: syncRes.addedMethods });
        }
      }
      writtenMap.set(hwPath, hwRec);
    }

    // Starter handwritten Guice bindings module (never overwritten once created) so
    // BootstrapModule.installOptionalModule("<pkg>.modules.HandwrittenBindingsModule") wires
    // GeneratedBindingsModule (which itself installs ProjectionModule when ReadModels exist) out of the box!
    const hwBindingsContent = [
      `// Handwritten DI bindings isolation zone for ${packageName}.`,
      '// BootstrapModule automatically loads this module via installOptionalModule.',
      '// GeneratedBindingsModule provides default bindings for Computations (L2 -> *Impl, L1-only -> Noop), ReadSide/ProjectionModule, ToolGates, Effects, *Impl handlers, and SagaCoordinatorBootstrap.',
      '// Override or add custom infrastructure / DomainService bindings below; truthsrc generate-v2 will never overwrite this file.',
      `package ${packageName}.modules`,
      '',
      'import com.google.inject.AbstractModule',
      '',
      'final class HandwrittenBindingsModule extends AbstractModule {',
      '  override def configure(): Unit = {',
      '    install(new GeneratedBindingsModule())',
      '  }',
      '}',
      '',
    ].join('\n');
    writtenMap.set(hwBindingsRel, writeArtifact(root, hwBindingsRel, hwBindingsContent, { overwrite: overwriteCloze }));
  }

  for (const rec of writtenMap.values()) written.push(rec);

  // Prune stale compiler-owned scaffold files and untouched starter handwritten files from previous generations.
  // Never deletes user-modified handwritten files; instead reports them in staleHandwrittenFiles.
  const manifestRel = '.truthsrc/generated-scala-manifest.json';
  const manifestAbs = join(root, manifestRel);
  const currentScaffoldPaths = new Set(
    [...writtenMap.keys()].filter(p => p.startsWith('generated-scaffold/')),
  );
  const currentHandwrittenPaths = new Set(
    [...writtenMap.keys()].filter(p => p.startsWith('handwritten/')),
  );
  const prunedHandwrittenFiles = [];
  const staleHandwrittenFiles = [];
  let prevManifest = null;
  if (existsSync(manifestAbs)) {
    try {
      prevManifest = JSON.parse(readFileSync(manifestAbs, 'utf8'));
      for (const oldRel of prevManifest.scaffoldPaths ?? []) {
        if (typeof oldRel === 'string' && oldRel.startsWith('generated-scaffold/') && !currentScaffoldPaths.has(oldRel)) {
          const staleAbs = join(root, oldRel);
          if (existsSync(staleAbs)) {
            unlinkSync(staleAbs);
            pruneEmptyAncestors(dirname(staleAbs), join(root, 'generated-scaffold'));
          }
        }
      }
      for (const [oldHwRel, starterSha] of Object.entries(prevManifest.starterHandwrittenHashes ?? {})) {
        if (typeof oldHwRel !== 'string' || !oldHwRel.startsWith('handwritten/') || currentHandwrittenPaths.has(oldHwRel)) {
          continue;
        }
        const oldHwAbs = join(root, oldHwRel);
        if (!existsSync(oldHwAbs)) continue;
        const curSha = createHash('sha256').update(readFileSync(oldHwAbs, 'utf8')).digest('hex');
        if (curSha === starterSha) {
          unlinkSync(oldHwAbs);
          pruneEmptyAncestors(dirname(oldHwAbs), join(root, 'handwritten'));
          prunedHandwrittenFiles.push(oldHwRel);
        } else {
          staleHandwrittenFiles.push({
            path: oldHwRel,
            code: 'STALE_HANDWRITTEN_FILE',
            message: `handwritten file "${oldHwRel}" belongs to a removed package or symbol and has local edits; migrate or remove it manually`,
          });
        }
      }
      if (prevManifest.packageName && prevManifest.packageName !== packageName) {
        const prevPkgDir = prevManifest.packageName.split('.').join('/');
        const staleManagedProtoDir = join(
          root,
          'generated-scaffold',
          'target',
          'scala-2.13',
          'src_managed',
          'main',
          prevPkgDir,
          'infrastructure',
          'proto',
        );
        if (existsSync(staleManagedProtoDir)) {
          rmSync(staleManagedProtoDir, { recursive: true, force: true });
        }
      }
    } catch {
      // ignore malformed prior manifest
    }
  }
  if (!emitCommonKernel) {
    for (const staleKernel of ['CommonTypes.scala', 'CborSerializable.scala']) {
      const staleRel = `generated-scaffold/scala/${commonPkgDir}/${staleKernel}`;
      if (!currentScaffoldPaths.has(staleRel)) {
        const staleAbs = join(root, staleRel);
        if (existsSync(staleAbs)) unlinkSync(staleAbs);
      }
    }
  }

  const nextStarterHandwrittenHashes = {};
  for (const hwRel of [...currentHandwrittenPaths].sort()) {
    const rec = writtenMap.get(hwRel);
    if (rec && !rec.skippedExisting && rec.sha256) {
      nextStarterHandwrittenHashes[hwRel] = rec.sha256;
    } else if (prevManifest?.starterHandwrittenHashes?.[hwRel]) {
      nextStarterHandwrittenHashes[hwRel] = prevManifest.starterHandwrittenHashes[hwRel];
    }
  }
  writeArtifact(
    root,
    manifestRel,
    `${JSON.stringify({
      schemaVersion: 'co-arising.generated-scala-manifest/v1',
      packageName,
      scaffoldPaths: [...currentScaffoldPaths].sort(),
      starterHandwrittenHashes: nextStarterHandwrittenHashes,
    }, null, 2)}\n`,
    { overwrite: true },
  );

  return {
    schemaVersion: 'co-arising.generate-v2/v1',
    generator: `${GENERATOR_MANIFEST.name}:${GENERATOR_MANIFEST.version}`,
    generatorSchemaVersion: GENERATOR_MANIFEST.schemaVersion,
    target: 'scala-cqrs-play-service-v2',
    architecture: '1.0-strict-governance-full',
    generatedHeader: GENERATED_HEADER_SCALA,
    familiesUsed: [...allFamilies],
    packagedSubdomains: canonicalV2.packagedSubdomains ?? [canonicalV2.context || canonicalV2.subdomain || 'core'],
    packageName,
    canonicalSha256: sha,
    outDir: root,
    files: written,
    syncedHandwrittenMethods,
    prunedHandwrittenFiles,
    staleHandwrittenFiles,
    handwrittenDrift,
  };
}

/**
 * Multi-Subdomain -> Single Bounded Context packaging entrypoint.
 * Packages multiple subdomain canonical-v2 models assigned to one BC in domain-map.yaml
 * into a single unified Play/sbt service with cross-BC ExternalEventBridge wiring.
 */
export function generateScalaCqrsPlayServiceV2ForBc({
  domainMap = null,
  bcName,
  canonicals,
  outDir,
  packageName = null,
  packaging = 'auto',
  overwriteCloze = false,
  runtimeProfile = null,
  includeCommonKernel = true,
  includeFrameworkLayers = true,
} = {}) {
  const isMonolith = packaging === 'monolith' || !domainMap;
  const bcSpec = !isMonolith
    ? ((domainMap?.boundedContexts ?? []).find(b => b.name === bcName) ?? null)
    : null;
  let selected = canonicals;
  if (bcSpec && Array.isArray(bcSpec.subdomains) && bcSpec.subdomains.length > 0) {
    const allowed = new Set(bcSpec.subdomains);
    const filtered = canonicals.filter(c => allowed.has(c.subdomain) || allowed.has(c.context));
    if (filtered.length > 0) selected = filtered;
  }
  const { mergedCanonical, externalIntegrations } = mergeCanonicalsForBc(selected, {
    bcName,
    domainMap: isMonolith ? null : domainMap,
  });
  const effPkg = packageName || bcSpec?.package || `example.${String(bcName || mergedCanonical.context).replace(/[^a-z0-9_]/giu, '').toLowerCase()}`;
  const res = generateScalaCqrsPlayServiceV2(mergedCanonical, {
    outDir,
    packageName: effPkg,
    overwriteCloze,
    runtimeProfile,
    includeCommonKernel,
    includeFrameworkLayers,
    externalIntegrations,
  });

  // Persist merged BC canonical (both BC-specific and default .truthsrc/canonical-v2.json) & SQLite knowledge DB
  // so tasks-v2 / emit-tests-v2 / verify-v2 / view-v2 work out of the box with zero flags!
  const root = resolve(outDir);
  const canonicalJsonText = `${JSON.stringify(mergedCanonical, null, 2)}\n`;
  const mergedCanonicalRel = `.truthsrc/bc-${bcName || mergedCanonical.context}-canonical-v2.json`;
  writeArtifact(root, mergedCanonicalRel, canonicalJsonText, { overwrite: true });
  writeArtifact(root, '.truthsrc/canonical-v2.json', canonicalJsonText, { overwrite: true });
  const dbPath = join(root, '.truthsrc/knowledge.sqlite');
  writeV2KnowledgeGraph(dbPath, mergedCanonical);

  return {
    ...res,
    packaging: isMonolith ? 'monolith' : 'context-map',
    boundedContext: bcName || mergedCanonical.context,
    canonicalPath: join(root, '.truthsrc/canonical-v2.json'),
    mergedCanonicalPath: join(root, mergedCanonicalRel),
    dbPath,
    externalIntegrationsCount: externalIntegrations.length,
  };
}

export const scalaCqrsPlayServiceV2Plugin = registerCodegenPlugin({
  target: 'scala-cqrs-play-service-v2',
  generate: generateScalaCqrsPlayServiceV2,
});
